def orbit_ab(i,j):
    if i==0 and j==0: return sympy.Integer(1)
    if j==0: return D(i,a)+D(i,b)
    if i==j: return D(i,a)*D(i,b)
    return D(i,a)*D(j,b)+D(j,a)*D(i,b)
def to_uw(P):
    # P symmetric poly in a,b over GF(2) -> poly in u=a+b, w=ab
    P=Poly(P,a,b,modulus=2); out=Poly(0,u,w,modulus=2)
    while not P.is_zero:
        (i,j),c=max(P.terms(),key=lambda t:(t[0][0],t[0][1]))  # lex leading a^i b^j, i>=j
        k=j; l=i-j  # a^i b^j leading of w^j u^(i-j)
        out+=Poly(u**l*w**k,u,w,modulus=2)
        P=P-Poly(sympy.expand((a+b)**l*(a*b)**k),a,b,modulus=2)
